<student_code untrusted="true">
=== correct.ino ===
   1| // Lab 4: debounced button toggle
   2| // Button on D2 to GND (internal pull-up, LOW when pressed), LED on D13,
   3| // state printed on Serial1 at 9600 baud.
   4| 
   5| const int BUTTON_PIN = 2;
   6| const int LED_PIN = LED_BUILTIN;
   7| const unsigned long DEBOUNCE_MS = 4;  // reading must be stable this long
   8| 
   9| int lastReading = HIGH;   // raw reading from the previous loop
  10| int buttonState = HIGH;   // debounced state
  11| unsigned long lastChangeMs = 0;
  12| bool ledOn = false;
  13| 
  14| void setup() {
  15|   pinMode(BUTTON_PIN, INPUT_PULLUP);
  16|   pinMode(LED_PIN, OUTPUT);
  17|   digitalWrite(LED_PIN, LOW);
  18|   Serial1.begin(9600);
  19| }
  20| 
  21| void loop() {
  22|   int reading = digitalRead(BUTTON_PIN);
  23|   if (reading != lastReading) {
  24|     lastChangeMs = millis();  // still bouncing, restart the timer
  25|     lastReading = reading;
  26|   }
  27| 
  28|   if (millis() - lastChangeMs >= DEBOUNCE_MS && reading != buttonState) {
  29|     buttonState = reading;
  30|     if (buttonState == LOW) {  // new press
  31|       ledOn = !ledOn;
  32|       digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  33|       Serial1.println(ledOn ? "ON" : "OFF");
  34|     }
  35|   }
  36| }
</student_code>
